def facts():
    a = TY.TensorSpec.make((64, 64), "mx7a", {"nk": 1, "gm": 16})
    t = TY.TensorSpec.make((64, 32), "f16", {"tile": (16, 8)})
    n = TY.TensorSpec.make((64, 32), "f16", {"node": 1})
    plain = TY.TensorSpec.make((4, 32))
    return {
        "sorted": [k for k, _ in a.layout],
        "tiled": [t.tiled, n.tiled],
        "rowmajor": [t.rowmajor, n.rowmajor, a.rowmajor, plain.rowmajor],
    }
